import { readFileSync, writeFileSync } from 'node:fs'
import { getWhaleCorePrompt } from './persona/core.js'

const template = readFileSync(new URL('./bundle-template.yml', import.meta.url), 'utf8')
const marker = '@@WHALE_CORE@@'
if (template.split(marker).length !== 3) throw new Error('Expected the current and legacy persona placeholders')
const core = getWhaleCorePrompt().trimEnd().split('\n').join('\n' + ' '.repeat(16))
const output = ('# Generated by src/build-bundle.js from one persona definition.\n' + template.replaceAll(marker, core)).replace(/[ \t]+$/gm, '')
writeFileSync(new URL('../cordis.patch.yml', import.meta.url), output)
